const body = $input.item.json.body;
const items = body.items || [];

function formatPrice(price) {
  return new Intl.NumberFormat('fa-IR').format(price) + ' تومان';
}

const itemRows = items.map((item, index) => `
  <tr style="background: ${index % 2 === 0 ? '#f9f9f9' : '#ffffff'};">
    <td style="padding:12px 16px;border-bottom:1px solid #e0e0e0;text-align:right;">${item.name}</td>
    <td style="padding:12px 16px;border-bottom:1px solid #e0e0e0;text-align:center;">${item.quantity}</td>
    <td style="padding:12px 16px;border-bottom:1px solid #e0e0e0;text-align:center;">${formatPrice(item.unit_price)}</td>
    <td style="padding:12px 16px;border-bottom:1px solid #e0e0e0;text-align:center;font-weight:bold;color:#2e7d32;">${formatPrice(item.total_price)}</td>
  </tr>
`).join('');

const orderDate = new Date(body.created_at).toLocaleDateString('fa-IR', {
  year: 'numeric', month: 'long', day: 'numeric'
});

const grandTotal = (body.total_price || 0) + (body.shipping_cost || 0) - (body.discount || 0);

const html = `<!DOCTYPE html>
<html dir="rtl" lang="fa">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>تایید سفارش - آریو شاپ</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Tahoma,Arial,sans-serif;background:#f0f4f8;direction:rtl;color:#333}
.container{max-width:650px;margin:30px auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.12)}
.header{background:linear-gradient(135deg,#1a237e,#283593,#3949ab);padding:40px 30px;text-align:center}
.header h1{color:#fff;font-size:26px;font-weight:700;margin-bottom:8px}
.header p{color:rgba(255,255,255,.85);font-size:14px}
.badge{display:inline-block;background:#4caf50;color:#fff;border-radius:50px;padding:8px 24px;font-size:14px;margin:16px 0}
.body{padding:32px 30px}
.greeting{font-size:18px;font-weight:700;margin-bottom:8px;color:#1a237e}
.message{font-size:14px;color:#555;line-height:1.8;margin-bottom:28px}
.section-title{font-size:15px;font-weight:700;color:#333;margin-bottom:12px;padding-bottom:8px;border-bottom:2px solid #e8eaf6}
.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:28px}
.info-box{background:#f5f5f5;border-radius:10px;padding:14px 16px}
.info-box .label{font-size:11px;color:#888;margin-bottom:4px}
.info-box .value{font-size:14px;font-weight:700;color:#222}
table{width:100%;border-collapse:collapse;margin-bottom:20px;border:1px solid #e0e0e0}
thead{background:#1a237e;color:#fff}
thead th{padding:12px 16px;text-align:right;font-size:13px;font-weight:700}
.summary-box{background:#e8eaf6;border-radius:10px;padding:20px;margin-bottom:28px}
.summary-row{display:flex;justify-content:space-between;align-items:center;padding:6px 0;font-size:14px}
.summary-row.total{border-top:2px solid #3949ab;margin-top:10px;padding-top:14px;font-size:17px;font-weight:700;color:#1a237e}
.address-box{background:#f9fbe7;border:1px solid #c5e1a5;border-radius:10px;padding:16px;margin-bottom:28px;font-size:14px;line-height:1.7}
.footer{background:#1a237e;padding:24px;text-align:center}
.footer p{color:rgba(255,255,255,.7);font-size:12px;line-height:1.8}
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>🛍️ آریو شاپ</h1>
    <p>فروشگاه آنلاین</p>
    <div class="badge">✅ سفارش با موفقیت ثبت شد</div>
  </div>
  <div class="body">
    <p class="greeting">سلام ${body.customer_name} عزیز،</p>
    <p class="message">از خرید شما سپاسگزاریم! پرداخت شما با موفقیت انجام شد و سفارش شما در حال پردازش است.</p>
    <p class="section-title">📋 اطلاعات سفارش</p>
    <div class="info-grid">
      <div class="info-box"><div class="label">شماره سفارش</div><div class="value">${body.order_number}</div></div>
      <div class="info-box"><div class="label">تاریخ سفارش</div><div class="value">${orderDate}</div></div>
      <div class="info-box"><div class="label">وضعیت پرداخت</div><div class="value" style="color:#2e7d32">✅ پرداخت موفق</div></div>
      <div class="info-box"><div class="label">ایمیل</div><div class="value" style="direction:ltr;text-align:left;">${body.customer_email}</div></div>
    </div>
    <p class="section-title">🛒 اقلام سفارش</p>
    <table>
      <thead><tr><th>نام محصول</th><th style="text-align:center">تعداد</th><th style="text-align:center">قیمت واحد</th><th style="text-align:center">قیمت کل</th></tr></thead>
      <tbody>${itemRows}</tbody>
    </table>
    <div class="summary-box">
      <div class="summary-row"><span>جمع کالاها:</span><span>${formatPrice(body.total_price || 0)}</span></div>
      <div class="summary-row"><span>هزینه ارسال:</span><span>${body.shipping_cost > 0 ? formatPrice(body.shipping_cost) : 'رایگان'}</span></div>
      ${body.discount > 0 ? '<div class="summary-row" style="color:#c62828"><span>تخفیف:</span><span>-' + formatPrice(body.discount) + '</span></div>' : ''}
      <div class="summary-row total"><span>💰 مبلغ نهایی:</span><span>${formatPrice(grandTotal)}</span></div>
    </div>
    ${body.shipping_address ? '<p class="section-title">📍 آدرس ارسال</p><div class="address-box">' + body.shipping_address + '</div>' : ''}
    <p style="font-size:13px;color:#777;text-align:center;">در صورت هرگونه سوال با پشتیبانی ما تماس بگیرید.</p>
  </div>
  <div class="footer">
    <p>آریو شاپ | فروشگاه آنلاین<br>این ایمیل به صورت خودکار ارسال شده است.</p>
  </div>
</div>
</body>
</html>`;

return [{ json: { ...body, emailHtml: html, grandTotal, orderDate } }];
